1	import { cycleOption } from "../lib/cycle_option";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import type { PlayerEventDetailValue } from "../lib/events";
4	import { defineHook } from "../lib/hook";
5	import { PersistedRecord } from "../lib/persisted_record";
6	import { attachPlayerEventBuffer } from "../lib/player_event_buffer";
7	import {
8	  attachProgressBuffer,
9	  type ProgressBuffer,
10	} from "../lib/progress_buffer";
11	import { readerSettings } from "../lib/reader_settings_store";
12	import { scrollFollow } from "../lib/scroll_follow";
13	import { attachScrubber, fractionAt } from "../lib/scrubber";
14	import {
15	  isJsonObject,
16	  type JsonValue,
17	  parseWordTimings,
18	  type WordTiming,
19	  wordSelector,
20	} from "../lib/types";
21	import { attachWordMenu } from "./word_menu";
22	
23	interface AudioPlayerDataset {
24	  audioUrl: string;
25	  timingsUrl: string;
26	  initialPosition?: string;
27	  bookId?: string;
28	  bookTitle?: string;
29	  chapterTitle?: string;
30	  chapterId?: string;
31	  nextChapterId?: string;
32	  nextAudioUrl?: string;
33	  nextTimingsUrl?: string;
34	  nextChapterTitle?: string;
35	  prevChapterId?: string;
36	  prevAudioUrl?: string;
37	  prevTimingsUrl?: string;
38	  prevChapterTitle?: string;
39	}
40	
41	interface PlayerPrefs {
42	  readonly speed: number;
43	  readonly volume: number;
44	  readonly collapsed: boolean;
45	}
46	
47	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
48	  speed: 1,
49	  volume: 1,
50	  collapsed: false,
51	});
52	
53	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
54	
55	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
56	
57	const POSITION_REPORT_INTERVAL_MS = 5000;
58	// Diagnostic heartbeat cadence while playing. Each heartbeat carries the
59	// wall-clock and audio-position deltas since the previous one — on a
60	// healthy player they match (scaled by playbackRate); divergence or a gap
61	// in the series is direct evidence of background throttling/suspension.
62	const HEARTBEAT_INTERVAL_MS = 30_000;
63	const SKIP_SECONDS = 10;
64	const AUTO_SCROLL_GRACE_MS = 800;
65	
66	// Play/pause button glyphs. The LV template renders ▶ (as &#9654;) as the
67	// static default; the hook overwrites textContent on every audio play/pause.
68	const PLAY_GLYPH = "▶";
69	const PAUSE_GLYPH = "❚❚";
70	
71	function coercePlayerPrefs(raw: JsonValue): Partial<PlayerPrefs> {
72	  if (!isJsonObject(raw)) return {};
73	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
74	  if (typeof raw.speed === "number") out.speed = raw.speed;
75	  if (typeof raw.volume === "number") out.volume = raw.volume;
76	  if (typeof raw.collapsed === "boolean") out.collapsed = raw.collapsed;
77	  return out;
78	}
79	
80	function migrateLegacyPlayerPrefs(): void {
81	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
82	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
83	  const legacyVolume = localStorage.getItem("readaloud-volume");
84	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
85	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
86	    return;
87	  const migrated: PlayerPrefs = {
88	    speed:
89	      legacySpeed !== null
90	        ? Number.parseFloat(legacySpeed)
91	        : PLAYER_PREFS_DEFAULTS.speed,
92	    volume:
93	      legacyVolume !== null
94	        ? Number.parseFloat(legacyVolume)
95	        : PLAYER_PREFS_DEFAULTS.volume,
96	    collapsed: legacyCollapsed === "true",
97	  };
98	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
99	}
100	
101	migrateLegacyPlayerPrefs();
102	const playerPrefs = new PersistedRecord<PlayerPrefs>(
103	  PLAYER_PREFS_KEY,
104	  PLAYER_PREFS_DEFAULTS,
105	  coercePlayerPrefs,
106	);
107	
108	function findActiveWord(
109	  timings: ReadonlyArray<WordTiming>,
110	  ms: number,
111	): number {
112	  let idx = -1;
113	  let lo = 0;
114	  let hi = timings.length - 1;
115	  while (lo <= hi) {
116	    const mid = (lo + hi) >>> 1;
117	    const t = timings[mid];
118	    if (!t) break;
119	    if (ms >= t.startMs && ms < t.endMs) {
120	      idx = mid;
121	      break;
122	    } else if (ms < t.startMs) {
123	      hi = mid - 1;
124	    } else {
125	      idx = mid;
126	      lo = mid + 1;
127	    }
128	  }
129	  if (idx >= 0 && idx < timings.length - 1) {
130	    const next = timings[idx + 1];
131	    if (next && ms >= next.startMs) idx += 1;
132	  }
133	  return idx;
134	}
135	
136	function formatTime(secs: number): string {
137	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
138	  const m = Math.floor(secs / 60);
139	  const s = Math.floor(secs % 60);
140	  return `${m}:${s < 10 ? "0" : ""}${s}`;
141	}
142	
143	// Monotonically increasing player-instance ID. Each hook mount gets one;
144	// shows up in every log line so we can tell apart pre-/post-remount
145	// instances when reading the browser console after the fact.
146	let nextPlayerId = 1;
147	
148	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
149	  (ctx) => {
150	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
151	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
152	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
153	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
154	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
155	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
156	
157	    if (!audio || !playPauseBtn) return;
158	
159	    const playerId = nextPlayerId++;
160	
161	    // `data-book-id` is set by the LV template and is part of the hook's
162	    // contract — if it's ever missing or unparseable, that's a template
163	    // bug and we want to fail loudly at mount, not silently no-op every
164	    // observation downstream.
165	    const bookId = Number.parseInt(ctx.dataset.bookId ?? "", 10);
166	    if (!Number.isFinite(bookId)) {
167	      throw new Error(
168	        "AudioPlayerHook: data-book-id is missing or unparseable",
169	      );
170	    }
171	
172	    // Durable diagnostic-event buffer. Every log() call below lands here
173	    // too, giving the server (→ journald → Loki + Prometheus) the same
174	    // event stream the browser console gets — that's what lets us debug
175	    // background-playback weirdness on a phone after the fact, without
176	    // the phone attached to a devtools session.
177	    const events = attachPlayerEventBuffer({
178	      bookId,
179	      beaconUrl: `/api/books/${bookId}/player-events`,
180	      pushEvents: (batch) => {
181	        ctx.pushEvent("player_events", { events: batch });
182	      },
183	    });
184	    ctx.onDestroy(() => events.detach());
185	
186	    // Detailed always-on logging for autoplay debugging. When the user
187	    // reports a symptom ("phone woke up at 11:07 and audio was at 0:00")
188	    // these lines + the chapter/book ids let us line up the JS-side state
189	    // machine with server logs (see reader_live.ex Logger.info calls).
190	    type LogValue = string | number | boolean | null | undefined;
191	    const log = (event: string, extra?: Record<string, LogValue>): void => {
192	      const wall = new Date().toISOString();
193	      const t =
194	        typeof performance !== "undefined"
195	          ? Math.round(performance.now())
196	          : Date.now();
197	      const base: Record<string, LogValue> = {
198	        player: playerId,
199	        chapter: ctx.dataset.chapterId,
200	        t,
201	      };
202	      if (extra) Object.assign(base, extra);
203	      // Always-on autoplay telemetry per the comment above; this is
204	      // intentional production logging, not debug residue.
205	      // ast-grep-ignore: no-console-log
206	      console.log(`[autoplay ${wall}] ${event}`, base);
207	
208	      // Mirror to the server-side diagnostic channel. `undefined` values
209	      // are dropped (they don't survive JSON anyway).
210	      const detail: Record<string, PlayerEventDetailValue> = {
211	        player: playerId,
212	      };
213	      if (extra) {
214	        for (const [key, value] of Object.entries(extra)) {
215	          if (value !== undefined) detail[key] = value;
216	        }
217	      }
218	      const fields: {
219	        chapter_id?: string;
220	        position_ms?: number;
221	        detail?: Record<string, PlayerEventDetailValue>;
222	      } = { position_ms: Math.round(audio.currentTime * 1000), detail };
223	      const chapterId = ctx.dataset.chapterId;
224	      if (chapterId !== undefined) fields.chapter_id = chapterId;
225	      events.record(event, fields);
226	    };
227	
228	    let timings: ReadonlyArray<WordTiming> = [];
229	    let currentWordIndex = -1;
230	    let lastReportedMs = -1;
231	    // Heartbeat state; wall=0 means "no previous beat" (start of playback,
232	    // or invalidated by pause/seek so deltas never span a discontinuity).
233	    let lastHeartbeatWall = 0;
234	    let lastHeartbeatPosMs = 0;
235	    let rafId: number | undefined;
236	    let wordMenuCleanup: (() => void) | undefined;
237	    let intersectionObserver: IntersectionObserver | undefined;
238	
239	    // Durable position-observation buffer. The hook owns the lifetime;
240	    // localStorage owns the cross-mount state (so a buffered observation
241	    // from before a LV remount or page-hide drains on the next mount).
242	    const progress: ProgressBuffer = attachProgressBuffer({
243	      bookId,
244	      beaconUrl: `/api/books/${bookId}/progress`,
245	      pushObservations: (observations) => {
246	        ctx.pushEvent("progress_observations", { observations });
247	      },
248	    });
249	    ctx.onDestroy(() => progress.detach());
250	
251	    const updateTimeDisplay = (): void => {
252	      if (!timeDisplay) return;
253	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
254	    };
255	
256	    const updateSpeedBadge = (speed: number): void => {
257	      if (!speedBadge) return;
258	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
259	    };
260	
261	    const cycleSpeed = (direction: "up" | "down"): void => {
262	      const closest = SPEEDS.reduce((best, s) =>
263	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
264	          ? s
265	          : best,
266	      );
267	      playerPrefs.set({ speed: cycleOption(SPEEDS, closest, direction) });
268	    };
269	
270	    const togglePlayback = (): void => {
271	      if (audio.paused) audio.play();
272	      else audio.pause();
273	    };
274	
275	    const seekToWordIndex = (idx: number): void => {
276	      const t = timings[idx];
277	      if (!t) return;
278	      audio.currentTime = t.startMs / 1000;
279	      if (audio.paused) audio.play();
280	    };
281	
282	    // Word highlighting with auto-scroll
283	    const highlightWord = (ms: number): void => {
284	      if (!textContainer || timings.length === 0) return;
285	      const idx = findActiveWord(timings, ms);
286	      if (idx === currentWordIndex) return;
287	
288	      if (currentWordIndex >= 0) {
289	        const old = textContainer.querySelector<HTMLElement>(
290	          wordSelector(currentWordIndex),
291	        );
292	        old?.classList.remove("word-active");
293	        old?.classList.add("word-spoken");
294	      }
295	
296	      if (idx >= 0) {
297	        const next = textContainer.querySelector<HTMLElement>(
298	          wordSelector(idx),
299	        );
300	        if (next) {
301	          next.classList.add("word-active");
302	          next.classList.remove("word-spoken");
303	
304	          if (!scrollFollow.get().autoScrollPaused) {
305	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
306	            next.scrollIntoView({ behavior: "smooth", block: "center" });
307	            if (intersectionObserver) {
308	              intersectionObserver.disconnect();
309	              intersectionObserver.observe(next);
310	            }
311	          }
312	        }
313	      }
314	
315	      if (idx > currentWordIndex) {
316	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
317	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
318	          if (el) {
319	            el.classList.remove("word-active");
320	            el.classList.add("word-spoken");
321	          }
322	        }
323	      } else if (idx >= 0 && idx < currentWordIndex) {
324	        for (let i = idx + 1; i <= currentWordIndex; i++) {
325	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
326	          if (el) el.classList.remove("word-spoken", "word-active");
327	        }
328	      }
329	
330	      currentWordIndex = idx;
331	    };
332	
333	    const startHighlightLoop = (): void => {
334	      const tick = (): void => {
335	        if (!audio.paused) {
336	          highlightWord(audio.currentTime * 1000);
337	          rafId = requestAnimationFrame(tick);
338	        }
339	      };
340	      rafId = requestAnimationFrame(tick);
341	    };
342	
343	    const stopHighlightLoop = (): void => {
344	      if (rafId !== undefined) {
345	        cancelAnimationFrame(rafId);
346	        rafId = undefined;
347	      }
348	    };
349	
350	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
351	      "[data-volume-slider]",
352	    );
353	
354	    // Player prefs → DOM. Bound to the store so chapter-swap re-renders can't
355	    // desync the slider, the speed badge, or the collapsed class from the
356	    // user's actual preference. The audio element's playbackRate/volume are
357	    // also re-applied here; src changes can reset playbackRate, so the
358	    // loadedmetadata handler below re-runs apply for that case.
359	    const applyPlayerPrefs = (p: Readonly<PlayerPrefs>): void => {
360	      audio.playbackRate = p.speed;
361	      audio.volume = p.volume;
362	      updateSpeedBadge(p.speed);
363	      if (volSlider) volSlider.value = String(p.volume);
364	      ctx.el.classList.toggle("collapsed", p.collapsed);
365	    };
366	    ctx.bindStore(playerPrefs, applyPlayerPrefs);
367	
368	    // The <audio> element has phx-update="ignore" so it's preserved across
369	    // chapter switches (push_patch) AND across LV reconnect/re-mount. The
370	    // hook itself, however, is destroyed and re-mounted on a re-mount —
371	    // so on mount we may find an <audio> element that's already loaded
372	    // (and possibly mid-playback) from a previous hook instance. In that
373	    // case we MUST NOT touch its src — doing so would interrupt the
374	    // user's listening session, which is exactly the bug we're chasing
375	    // with sleeping-mobile autoplay (LV WebSocket times out → re-mount on
376	    // wake → forced reload → 00:00/00:00).
377	    //
378	    // Heuristic: only set src if the element doesn't have one yet (or
379	    // has the page URL, the default for an unset <audio>). If it has
380	    // any other src — network URL, or a `blob:` URL prefetched by a
381	    // previous hook instance — leave it alone.
382	    const wantSrc = ctx.dataset.audioUrl;
383	    const existingSrc = audio.src;
384	    const hasMeaningfulSrc =
385	      existingSrc !== "" &&
386	      existingSrc !== window.location.href &&
387	      existingSrc !== `${window.location.origin}/`;
388	    log("mount", {
389	      hasMeaningfulSrc,
390	      existingSrcKind: existingSrc.startsWith("blob:")
391	        ? "blob"
392	        : existingSrc === "" || existingSrc === window.location.href
393	          ? "empty"
394	          : "url",
395	      audioPaused: audio.paused,
396	      audioCurrentTime: audio.currentTime,
397	      audioReadyState: audio.readyState,
398	      autoNextChapter: readerSettings.get().autoNextChapter,
399	      hasNext: !!ctx.dataset.nextAudioUrl,
400	      hasPrev: !!ctx.dataset.prevAudioUrl,
401	      bookTitle: ctx.dataset.bookTitle,
402	      chapterTitle: ctx.dataset.chapterTitle,
403	    });
404	    if (!hasMeaningfulSrc) {
405	      log("set-initial-src");
406	      audio.src = wantSrc;
407	      audio.load();
408	    } else {
409	      log("preserve-existing-src");
410	    }
411	
412	    ctx.on(audio, "loadedmetadata", () => {
413	      applyPlayerPrefs(playerPrefs.get());
414	      updateTimeDisplay();
415	      updateMediaSessionPosition();
416	    });
417	    ctx.on(audio, "durationchange", updateTimeDisplay);
418	
419	    // Word timings — fetched on mount and re-fetched whenever we swap to a
420	    // new chapter via swapToChapter().
421	    const fetchTimings = (url: string): void => {
422	      timings = [];
423	      currentWordIndex = -1;
424	      fetch(url)
425	        .then((r) => r.json())
426	        .then((data: JsonValue) => {
427	          timings = parseWordTimings(data);
428	          if (textContainer && !wordMenuCleanup)
429	            wordMenuCleanup = attachWordMenu(textContainer);
430	        })
431	        .catch((err: Error) =>
432	          console.error("AudioPlayer: failed to load timings", err),
433	        );
434	    };
435	    fetchTimings(ctx.dataset.timingsUrl);
436	
437	    // Restore initial position — only on a fresh load. On re-mount of an
438	    // already-playing element we'd otherwise rewind the user back to a
439	    // saved position from a different LV session.
440	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
441	    if (initialMs > 0 && !hasMeaningfulSrc) {
442	      ctx.on(
443	        audio,
444	        "loadedmetadata",
445	        () => {
446	          audio.currentTime = initialMs / 1000;
447	        },
448	        { once: true },
449	      );
450	    }
451	
452	    // --- Media Session API ----------------------------------------------
453	    // Registers the OS-level lock-screen / notification controls. Without
454	    // this, a sleeping mobile device has no native "next chapter" button
455	    // and the WebSocket-bound LV nav often fails when the device wakes.
456	    // With this, the OS gives us a working next/prev button even when JS
457	    // is throttled, and the audio session keeps the lock screen UI alive
458	    // across chapter swaps (since we reuse the same <audio> element).
459	    const ms =
460	      typeof navigator !== "undefined" && "mediaSession" in navigator
461	        ? navigator.mediaSession
462	        : null;
463	
464	    const updateMediaSessionMetadata = (): void => {
465	      if (!ms) return;
466	      ms.metadata = new MediaMetadata({
467	        title: ctx.dataset.chapterTitle ?? "",
468	        artist: ctx.dataset.bookTitle ?? "",
469	        album: ctx.dataset.bookTitle ?? "",
470	      });
471	    };
472	
473	    const updateMediaSessionPosition = (): void => {
474	      if (!ms?.setPositionState) return;
475	      if (!Number.isFinite(audio.duration) || audio.duration <= 0) return;
476	      try {
477	        ms.setPositionState({
478	          duration: audio.duration,
479	          position: Math.min(audio.currentTime, audio.duration),
480	          playbackRate: audio.playbackRate || 1,
481	        });
482	      } catch {
483	        // Some browsers throw on invalid positions; ignore.
484	      }
485	    };
486	
487	    // --- Next-chapter prefetch -----------------------------------------
488	    // Mobile browsers (iOS Safari especially) suspend network fetches
489	    // when the screen locks. If we wait until `ended` to fetch the next
490	    // chapter's audio, the request stalls and audio.play() never gets a
491	    // valid resource — exactly the bug we're chasing. So while the
492	    // current chapter is still playing (and the device presumably
493	    // awake), download the next chapter's audio fully into a Blob URL.
494	    // On `ended` we swap to the in-memory blob — no network needed.
495	    let currentBlobUrl: string | null = null; // points to in-use audio.src
496	    let prefetchedBlobUrl: string | null = null;
497	    let prefetchedFor: string | null = null;
498	    let prefetchAbort: AbortController | null = null;
499	
500	    const tryStartPrefetch = (): void => {
501	      if (!readerSettings.get().autoNextChapter) return;
502	      const url = ctx.dataset.nextAudioUrl;
503	      if (!url) return;
504	      // Already done or in flight for the same URL? Skip.
505	      if (prefetchedBlobUrl && prefetchedFor === url) return;
506	      if (prefetchAbort && prefetchedFor === url) return;
507	      // Target URL changed (e.g. user manually jumped chapters) — drop
508	      // any in-flight or stale-blob state and restart.
509	      if (prefetchAbort) {
510	        log("prefetch-abort-stale", { for: prefetchedFor });
511	        prefetchAbort.abort();
512	        prefetchAbort = null;
513	      }
514	      if (prefetchedBlobUrl) {
515	        log("prefetch-revoke-stale", { for: prefetchedFor });
516	        URL.revokeObjectURL(prefetchedBlobUrl);
517	        prefetchedBlobUrl = null;
518	      }
519	      prefetchedFor = url;
520	      const abort = new AbortController();
521	      prefetchAbort = abort;
522	      log("prefetch-start", { url });
523	      const startedAt = performance.now();
524	      fetch(url, { signal: abort.signal })
525	        .then((r) => {
526	          if (!r.ok) throw new Error(`HTTP ${r.status}`);
527	          return r.blob();
528	        })
529	        .then((blob) => {
530	          prefetchAbort = null;
531	          if (prefetchedFor !== url) {
532	            log("prefetch-discard-target-changed", {
533	              completedFor: url,
534	              currentTarget: prefetchedFor,
535	            });
536	            return;
537	          }
538	          prefetchedBlobUrl = URL.createObjectURL(blob);
539	          log("prefetch-done", {
540	            url,
541	            bytes: blob.size,
542	            durationMs: Math.round(performance.now() - startedAt),
543	          });
544	        })
545	        .catch((err: Error) => {
546	          prefetchAbort = null;
547	          if (err.name !== "AbortError") {
548	            log("prefetch-fail", { url, error: String(err) });
549	            console.warn("AudioPlayer: next-chapter prefetch failed", err);
550	            // Reset prefetchedFor so we can retry later (e.g. on next
551	            // timeupdate) instead of being stuck thinking we're done.
552	            if (prefetchedFor === url) prefetchedFor = null;
553	          } else {
554	            log("prefetch-aborted", { url });
555	          }
556	        });
557	    };
558	
559	    // Swap to a different chapter without unmounting the player. Used by
560	    // both the auto-next-on-ended path and (if invoked from outside) by
561	    // server-pushed chapter changes. Critically: same <audio> element, so
562	    // the OS audio session is preserved and lock-screen playback continues
563	    // without requiring a new user gesture.
564	    const swapToChapter = (
565	      audioUrl: string,
566	      timingsUrl: string,
567	      chapterTitle: string,
568	    ): void => {
569	      log("swap-to-chapter", {
570	        srcKind: audioUrl.startsWith("blob:") ? "blob" : "url",
571	        chapterTitle,
572	        audioPaused: audio.paused,
573	      });
574	      audio.src = audioUrl;
575	      audio.load();
576	      // Update title eagerly so the lock screen shows the new chapter name
577	      // even before the LV push_patch round-trip lands.
578	      if (ms) {
579	        ms.metadata = new MediaMetadata({
580	          title: chapterTitle,
581	          artist: ctx.dataset.bookTitle ?? "",
582	          album: ctx.dataset.bookTitle ?? "",
583	        });
584	      }
585	      fetchTimings(timingsUrl);
586	      audio
587	        .play()
588	        .then(() => log("swap-play-ok"))
589	        .catch((err: Error) => {
590	          log("swap-play-blocked", { error: String(err) });
591	          console.warn("AudioPlayer: chapter-swap play blocked", err);
592	        });
593	    };
594	
595	    // Build a /books/:bookId/read/:chapterId?nav=internal URL by swapping
596	    // the chapter id in the current pathname. The current path always
597	    // matches /books/:bookId/read/:N (we're rendering the reader LV), so
598	    // a regex replace is enough — no need to thread book_id through the
599	    // hook's dataset. Returns null if the pathname isn't on the reader.
600	    const buildReaderUrl = (chapterId: string): string | null => {
601	      const path = window.location.pathname;
602	      if (!/\/books\/\d+\/read\/\d+/.test(path)) return null;
603	      return `${path.replace(/\/read\/\d+/, `/read/${chapterId}`)}?nav=internal`;
604	    };
605	
606	    const goToNextChapter = (): boolean => {
607	      const networkUrl = ctx.dataset.nextAudioUrl;
608	      const timingsUrl = ctx.dataset.nextTimingsUrl;
609	      const title = ctx.dataset.nextChapterTitle ?? "";
610	      const nextChapterId = ctx.dataset.nextChapterId;
611	      if (!networkUrl || !timingsUrl || !nextChapterId) {
612	        log("next-chapter-blocked-no-target", {
613	          hasUrl: !!networkUrl,
614	          hasTimings: !!timingsUrl,
615	          hasChapterId: !!nextChapterId,
616	        });
617	        return false;
618	      }
619	
620	      // Use the prefetched in-memory blob if it's for THIS URL — this is
621	      // the whole point of prefetch and is what makes background-tab
622	      // autoplay actually work. Fall back to the network URL otherwise
623	      // (e.g. desktop user who never triggered prefetch).
624	      const audioUrl =
625	        prefetchedBlobUrl !== null && prefetchedFor === networkUrl
626	          ? prefetchedBlobUrl
627	          : networkUrl;
628	      const useBlob = audioUrl !== networkUrl;
629	      log("go-to-next-chapter", {
630	        useBlob,
631	        prefetchedFor,
632	        prefetchInFlight: prefetchAbort !== null,
633	        toTitle: title,
634	      });
635	
636	      // The blob currently in use as audio.src (if any) is being replaced
637	      // — revoke it so we don't leak ~tens of MB per chapter swap.
638	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
639	      currentBlobUrl = useBlob ? audioUrl : null;
640	      // Detach the prefetched-blob slot since it's now the current one
641	      // (or we didn't use it). Either way, the next prefetch (for the
642	      // chapter after this) starts fresh.
643	      prefetchedBlobUrl = null;
644	      prefetchedFor = null;
645	      if (prefetchAbort) {
646	        prefetchAbort.abort();
647	        prefetchAbort = null;
648	      }
649	
650	      swapToChapter(audioUrl, timingsUrl, title);
651	
652	      // Update browser URL client-side BEFORE notifying the server. This
653	      // is the critical fix for sleeping-mobile autoplay: server-side
654	      // push_patch only updates the URL when its diff reaches the
655	      // client, which doesn't happen if the WebSocket is suspended (and
656	      // the LV process times out before delivery). With this pushState
657	      // the URL stays in sync with audio.src regardless of WS state, so
658	      // a refresh after wake lands on the chapter that's actually
659	      // playing — not the previous one.
660	      const newUrl = buildReaderUrl(nextChapterId);
661	      if (newUrl) {
662	        history.pushState({}, "", newUrl);
663	        log("history-pushstate", { url: newUrl });
664	      }
665	
666	      // Persist the pivot through the durable buffer. If the WS is
667	      // suspended (mobile lock — the original autoplay-stranding bug),
668	      // the buffer falls back to sendBeacon on visibilitychange:hidden
669	      // so the new chapter / 0:00 reset survives even with a dead WS.
670	      progress.observe({
671	        chapter_id: nextChapterId,
672	        audio_position_ms: 0,
673	        scroll_position: 0,
674	      });
675	
676	      // Tell the server to reload chapter assigns. `client_owned: true`
677	      // means JS owns BOTH the URL update (already pushState'd above)
678	      // AND the persistence write (already buffered above), so the
679	      // server skips its own push_patch and observe! — pushing twice
680	      // would create a duplicate history entry, and observing twice
681	      // would race with the buffered drain.
682	      log("push-event", { event: "next_chapter" });
683	      ctx.pushEvent("next_chapter", { client_owned: true });
684	      return true;
685	    };
686	
687	    const goToPrevChapter = (): boolean => {
688	      const url = ctx.dataset.prevAudioUrl;
689	      const timingsUrl = ctx.dataset.prevTimingsUrl;
690	      const title = ctx.dataset.prevChapterTitle ?? "";
691	      const prevChapterId = ctx.dataset.prevChapterId;
692	      if (!url || !timingsUrl || !prevChapterId) {
693	        log("prev-chapter-blocked-no-target");
694	        return false;
695	      }
696	      log("go-to-prev-chapter", { toTitle: title });
697	      swapToChapter(url, timingsUrl, title);
698	
699	      // Same client-side URL update + persistence as next-chapter; see
700	      // the comment block in goToNextChapter for the full rationale.
701	      const newUrl = buildReaderUrl(prevChapterId);
702	      if (newUrl) {
703	        history.pushState({}, "", newUrl);
704	        log("history-pushstate", { url: newUrl });
705	      }
706	
707	      progress.observe({
708	        chapter_id: prevChapterId,
709	        audio_position_ms: 0,
710	        scroll_position: 0,
711	      });
712	
713	      log("push-event", { event: "prev_chapter" });
714	      ctx.pushEvent("prev_chapter", { client_owned: true });
715	      return true;
716	    };
717	
718	    if (ms) {
719	      updateMediaSessionMetadata();
720	      const safeSet = (
721	        action: MediaSessionAction,
722	        handler: MediaSessionActionHandler | null,
723	      ): void => {
724	        try {
725	          ms.setActionHandler(action, handler);
726	        } catch {
727	          // Browser may not support this action — fine, skip it.
728	        }
729	      };
730	      safeSet("play", () => {
731	        audio.play().catch(() => {});
732	      });
733	      safeSet("pause", () => audio.pause());
734	      safeSet("seekbackward", (details) => {
735	        const delta = details.seekOffset ?? SKIP_SECONDS;
736	        audio.currentTime = Math.max(0, audio.currentTime - delta);
737	      });
738	      safeSet("seekforward", (details) => {
739	        const delta = details.seekOffset ?? SKIP_SECONDS;
740	        const max = Number.isFinite(audio.duration)
741	          ? audio.duration
742	          : Number.POSITIVE_INFINITY;
743	        audio.currentTime = Math.min(max, audio.currentTime + delta);
744	      });
745	      safeSet("seekto", (details) => {
746	        if (typeof details.seekTime === "number") {
