748	        }
749	      });
750	      // Only register next/prev when there's actually a target; otherwise
751	      // the OS UI shows greyed-out buttons (or nothing) which is correct.
752	      if (ctx.dataset.nextAudioUrl) {
753	        safeSet("nexttrack", () => {
754	          log("media-session-nexttrack");
755	          goToNextChapter();
756	        });
757	      } else {
758	        safeSet("nexttrack", null);
759	      }
760	      if (ctx.dataset.prevAudioUrl) {
761	        safeSet("previoustrack", () => {
762	          log("media-session-previoustrack");
763	          goToPrevChapter();
764	        });
765	      } else {
766	        safeSet("previoustrack", null);
767	      }
768	      ctx.onDestroy(() => {
769	        // Clear handlers + metadata so a stale player on a different page
770	        // doesn't get media-key events meant for nothing.
771	        const actions: readonly MediaSessionAction[] = [
772	          "play",
773	          "pause",
774	          "nexttrack",
775	          "previoustrack",
776	          "seekbackward",
777	          "seekforward",
778	          "seekto",
779	        ];
780	        for (const a of actions) {
781	          try {
782	            ms.setActionHandler(a, null);
783	          } catch {}
784	        }
785	        ms.metadata = null;
786	      });
787	    }
788	
789	    // Controls
790	    ctx.on(playPauseBtn, "click", togglePlayback);
791	
792	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
793	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
794	    if (skipBack) {
795	      ctx.on(skipBack, "click", () => {
796	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
797	      });
798	    }
799	    if (skipFwd) {
800	      ctx.on(skipFwd, "click", () => {
801	        const max = Number.isFinite(audio.duration)
802	          ? audio.duration
803	          : Number.POSITIVE_INFINITY;
804	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
805	      });
806	    }
807	
808	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
809	      "[data-collapse-toggle]",
810	    );
811	    if (collapseToggle) {
812	      ctx.on(collapseToggle, "click", () => {
813	        playerPrefs.set({ collapsed: !playerPrefs.get().collapsed });
814	      });
815	    }
816	
817	    if (volSlider) {
818	      ctx.on(volSlider, "input", () => {
819	        playerPrefs.set({ volume: Number.parseFloat(volSlider.value) });
820	      });
821	    }
822	
823	    // Scrubbers (main + mini)
824	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
825	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
826	    const seekToFraction = (f: number): void => {
827	      if (Number.isFinite(audio.duration))
828	        audio.currentTime = f * audio.duration;
829	    };
830	    for (const sc of [scrubMain, scrubMini]) {
831	      if (!sc) continue;
832	      const dispose = attachScrubber<number>({
833	        el: sc,
834	        indexAt: (clientX) => fractionAt(sc, clientX),
835	        preview: () => {},
836	        commit: seekToFraction,
837	      });
838	      ctx.onDestroy(dispose);
839	    }
840	
841	    // Time updates: progress bars + time display + position report.
842	    // Also kicks off the next-chapter prefetch once the user has clearly
843	    // committed to this chapter (>15% through). Doing it here, gated on
844	    // playback progress, means we don't waste bandwidth on chapters the
845	    // user opens and immediately abandons.
846	    const PREFETCH_TRIGGER_FRACTION = 0.15;
847	    ctx.on(audio, "timeupdate", () => {
848	      if (!audio.duration) return;
849	      const pct = (audio.currentTime / audio.duration) * 100;
850	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
851	      if (fill) fill.style.width = `${pct}%`;
852	      const fillMini = ctx.el.querySelector<HTMLElement>(
853	        "[data-progress-fill-mini]",
854	      );
855	      if (fillMini) fillMini.style.width = `${pct}%`;
856	      updateTimeDisplay();
857	
858	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
859	        tryStartPrefetch();
860	      }
861	
862	      const nowMs = Math.round(audio.currentTime * 1000);
863	      if (
864	        lastReportedMs < 0 ||
865	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
866	      ) {
867	        lastReportedMs = nowMs;
868	        const chapterId = ctx.dataset.chapterId;
869	        if (chapterId) {
870	          progress.observe({
871	            chapter_id: chapterId,
872	            audio_position_ms: nowMs,
873	          });
874	        }
875	      }
876	
877	      const wallNow = Date.now();
878	      if (
879	        !audio.paused &&
880	        wallNow - lastHeartbeatWall >= HEARTBEAT_INTERVAL_MS
881	      ) {
882	        log(
883	          "heartbeat",
884	          lastHeartbeatWall > 0
885	            ? {
886	                wallDeltaMs: wallNow - lastHeartbeatWall,
887	                audioDeltaMs: nowMs - lastHeartbeatPosMs,
888	                rate: audio.playbackRate,
889	              }
890	            : { rate: audio.playbackRate },
891	        );
892	        lastHeartbeatWall = wallNow;
893	        lastHeartbeatPosMs = nowMs;
894	      }
895	    });
896	
897	    // Play/pause icon — bound to the audio element's own state so it stays
898	    // in sync across morphdom patches (chapter swap re-renders #audio-player
899	    // and would otherwise reset the button text to the template default).
900	    ctx.bindElement(audio, ["play", "pause"], () => {
901	      playPauseBtn.textContent = audio.paused ? PLAY_GLYPH : PAUSE_GLYPH;
902	    });
903	
904	    // Side effects on play/pause that aren't DOM projection.
905	    ctx.on(audio, "play", () => {
906	      // Fresh heartbeat series — deltas must not span the paused gap.
907	      lastHeartbeatWall = 0;
908	      log("audio-play", {
909	        currentTime: audio.currentTime,
910	        duration: audio.duration,
911	      });
912	      scrollFollow.setPlaying(true);
913	      startHighlightLoop();
914	      if (ms) ms.playbackState = "playing";
915	      updateMediaSessionPosition();
916	    });
917	    ctx.on(audio, "pause", () => {
918	      log("audio-pause", {
919	        currentTime: audio.currentTime,
920	        duration: audio.duration,
921	        atEnd:
922	          Number.isFinite(audio.duration) &&
923	          audio.duration > 0 &&
924	          audio.currentTime >= audio.duration - 0.5,
925	      });
926	      scrollFollow.setPlaying(false);
927	      stopHighlightLoop();
928	      if (ms) ms.playbackState = "paused";
929	      const chapterId = ctx.dataset.chapterId;
930	      if (chapterId) {
931	        progress.observe({
932	          chapter_id: chapterId,
933	          audio_position_ms: Math.round(audio.currentTime * 1000),
934	        });
935	      }
936	    });
937	    ctx.on(audio, "ended", () => {
938	      log("audio-ended", {
939	        autoNext: readerSettings.get().autoNextChapter,
940	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
941	        prefetchInFlight: prefetchAbort !== null,
942	        prefetchedFor,
943	        nextUrl: ctx.dataset.nextAudioUrl ?? null,
944	      });
945	      stopHighlightLoop();
946	      if (readerSettings.get().autoNextChapter) {
947	        // JS-side chapter swap on the same <audio> element. This is the
948	        // critical path for sleeping-mobile autoplay: a full LV navigation
949	        // would tear down the OS audio session and silently fail when the
950	        // device is locked. Same-element src swap keeps the lock-screen
951	        // controls live and the audio session uninterrupted.
952	        goToNextChapter();
953	      }
954	    });
955	    ctx.on(audio, "error", () => {
956	      const err = audio.error;
957	      log("audio-error", {
958	        code: err?.code ?? null,
959	        message: err?.message ?? null,
960	        currentSrc: audio.currentSrc?.startsWith("blob:") ? "blob" : "url",
961	      });
962	    });
963	    ctx.on(audio, "stalled", () =>
964	      log("audio-stalled", { currentTime: audio.currentTime }),
965	    );
966	    ctx.on(audio, "waiting", () =>
967	      log("audio-waiting", { currentTime: audio.currentTime }),
968	    );
969	    ctx.on(audio, "loadedmetadata", () =>
970	      log("audio-loadedmetadata", { duration: audio.duration }),
971	    );
972	    ctx.on(audio, "seeked", () => {
973	      // A seek invalidates heartbeat deltas; restart the series.
974	      lastHeartbeatWall = 0;
975	      log("audio-seeked", { currentTime: audio.currentTime });
976	    });
977	
978	    // --- Background-state diagnostics ---------------------------------
979	    // The "weird state on mobile" reports all hinge on transitions the
980	    // console can't show us after the fact: screen lock / app switch
981	    // (visibilitychange), bfcache traversal (pageshow/pagehide), tab
982	    // freezing (freeze/resume — Page Lifecycle API, not in TS's event
983	    // maps, hence the manual listeners), and network loss. Snapshot the
984	    // <audio> element at every transition so the server-side trace shows
985	    // exactly what state playback was in when the platform intervened.
986	    const audioSnapshot = (): Record<string, LogValue> => ({
987	      paused: audio.paused,
988	      currentTime: Math.round(audio.currentTime * 100) / 100,
989	      readyState: audio.readyState,
990	      networkState: audio.networkState,
991	      srcKind: audio.currentSrc.startsWith("blob:") ? "blob" : "url",
992	    });
993	
994	    const onVisibilityChange = (): void => {
995	      log(
996	        document.visibilityState === "hidden"
997	          ? "visibility-hidden"
998	          : "visibility-visible",
999	        audioSnapshot(),
1000	      );
1001	    };
1002	    document.addEventListener("visibilitychange", onVisibilityChange);
1003	    ctx.onDestroy(() =>
1004	      document.removeEventListener("visibilitychange", onVisibilityChange),
1005	    );
1006	
1007	    const onFreeze = (): void => log("page-freeze", audioSnapshot());
1008	    const onResume = (): void => log("page-resume", audioSnapshot());
1009	    document.addEventListener("freeze", onFreeze);
1010	    document.addEventListener("resume", onResume);
1011	    ctx.onDestroy(() => {
1012	      document.removeEventListener("freeze", onFreeze);
1013	      document.removeEventListener("resume", onResume);
1014	    });
1015	
1016	    ctx.on(window, "pagehide", (e) =>
1017	      log("page-hide", { persisted: e.persisted, ...audioSnapshot() }),
1018	    );
1019	    ctx.on(window, "pageshow", (e) =>
1020	      log("page-show", { persisted: e.persisted, ...audioSnapshot() }),
1021	    );
1022	    ctx.on(window, "online", () => log("net-online", audioSnapshot()));
1023	    ctx.on(window, "offline", () => log("net-offline", audioSnapshot()));
1024	
1025	    // Re-sync UX
1026	    if (resyncBtn) {
1027	      ctx.on(resyncBtn, "click", () => {
1028	        scrollFollow.resume();
1029	        if (currentWordIndex >= 0 && textContainer) {
1030	          const el = textContainer.querySelector<HTMLElement>(
1031	            wordSelector(currentWordIndex),
1032	          );
1033	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
1034	        }
1035	      });
1036	    }
1037	
1038	    if (textContainer && "IntersectionObserver" in window) {
1039	      intersectionObserver = new IntersectionObserver(
1040	        (entries) => {
1041	          for (const entry of entries) {
1042	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
1043	              scrollFollow.resume();
1044	            }
1045	          }
1046	        },
1047	        { threshold: 0.5 },
1048	      );
1049	      ctx.onDestroy(() => intersectionObserver?.disconnect());
1050	    }
1051	
1052	    ctx.bindStore(scrollFollow, (s) => {
1053	      if (!resyncBtn) return;
1054	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
1055	    });
1056	
1057	    // Word menu actions
1058	    ctx.on(window, "word-action", (detail) => {
1059	      if (detail.kind === "play") seekToWordIndex(detail.index);
1060	    });
1061	
1062	    // Speed badge cycle
1063	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
1064	
1065	    // Keyboard-shortcut events
1066	    ctx.on(window, "audio:toggle-playback", togglePlayback);
1067	    ctx.on(window, "audio:toggle-mute", () => {
1068	      audio.muted = !audio.muted;
1069	    });
1070	    ctx.on(window, "audio:change-speed", ({ direction }) =>
1071	      cycleSpeed(direction),
1072	    );
1073	
1074	    // Manual chapter nav (floating-pill buttons + keyboard arrows). These
1075	    // dispatch a window event instead of phx-click="next_chapter" while
1076	    // the audio player is mounted so we can do a same-<audio>-element src
1077	    // swap instead of letting the server's push_patch leave us playing
1078	    // the previous chapter. When the next/prev chapter has no audio yet,
1079	    // goTo*Chapter returns false and we fall back to the server-owned
1080	    // path so the user can still navigate to audio-less chapters.
1081	    ctx.on(window, "audio:nav-next-chapter", () => {
1082	      log("nav-next-chapter-event");
1083	      if (!goToNextChapter()) ctx.pushEvent("next_chapter", {});
1084	    });
1085	    ctx.on(window, "audio:nav-prev-chapter", () => {
1086	      log("nav-prev-chapter-event");
1087	      if (!goToPrevChapter()) ctx.pushEvent("prev_chapter", {});
1088	    });
1089	
1090	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
1091	    // audio or revoke its current blob URL here. Destroy fires on LV
1092	    // reconnect/re-mount (long phone sleep → server LV process times out
1093	    // → client re-mount on wake) — and the <audio> element survives
1094	    // (phx-update="ignore"). Pausing or revoking would interrupt the
1095	    // user's listening session at exactly the moment they wake the phone
1096	    // hoping playback continues. If the player is genuinely going away
1097	    // (user navigates off the reader), the <audio> element gets removed
1098	    // from the DOM, which auto-pauses it — no explicit pause needed.
1099	    //
1100	    // We do still abort and revoke the *prefetch* slot: that blob is not
1101	    // tied to the playing audio element, so leaking it across re-mount
1102	    // would just waste memory.
1103	    ctx.onDestroy(() => {
1104	      log("destroy", {
1105	        audioPaused: audio.paused,
1106	        currentTime: audio.currentTime,
1107	        duration: audio.duration,
1108	        prefetchInFlight: prefetchAbort !== null,
1109	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
1110	      });
1111	      stopHighlightLoop();
1112	      wordMenuCleanup?.();
1113	      if (prefetchAbort) prefetchAbort.abort();
1114	      if (prefetchedBlobUrl) URL.revokeObjectURL(prefetchedBlobUrl);
1115	    });
1116	  },
1117	);
